"use strict";exports.id=396,exports.ids=[396],exports.modules={3396:t=>{t.exports=JSON.parse('{"meta":{"title":"OsonPrava — Ҳайдовчилик гувоҳномаси имтиҳонига тайёргарлик","description":"Ўзбекистонда ҳайдовчилик гувоҳномаси имтиҳонига бепул тайёрланинг. 1210+ савол, 61 билет, имтиҳон симуляцияси ва Октагон 1v1 режими."},"nav":{"home":"Бош саҳифа","blog":"Блог","signs":"Йўл белгилари","login":"Кириш","register":"Рўйхатдан ўтиш"},"hero":{"title":"Ҳайдовчилик гувоҳномасига тайёрланинг","titleHighlight":"осон ва тез","subtitle":"Ўзбекистондаги энг тўлиқ ва бепул ҳайдовчилик имтиҳонига тайёргарлик платформаси. 1210+ савол, реал имтиҳон симуляцияси ва дўстлар билан беллашув.","cta":"Бошлаш","ctaTelegram":"Телеграм Бот","rotatingWords":["осон","тез","бепул","қизиқарли"]},"stats":{"questions":"Саволлар","questionsCount":"1210+","tickets":"Билет","ticketsCount":"61","accuracy":"Бепул","accuracyCount":"100%","languages":"Тил","languagesCount":"3"},"features":{"title":"Имкониятлар","items":[{"title":"Билетлар бўйича тест","description":"61 та билетнинг ҳар бирини алоҳида ечиб, ўз билимингизни синаб кўринг.","icon":"ticket"},{"title":"Мавзулар бўйича тест","description":"Йўл ҳаракати қоидаларини мавзуларга бўлиб ўрганинг.","icon":"book"},{"title":"Имтиҳон симуляцияси","description":"Ҳақиқий имтиҳонга ўхшаш шароитда машқ қилинг — 30 савол, 20 дақиқа.","icon":"timer"},{"title":"Октагон 1v1","description":"Дўстларингиз билан реал вақтда беллашинг ва рейтингда ўсиб боринг.","icon":"swords"}]},"howItWorks":{"title":"Қандай ишлайди?","steps":[{"title":"Рўйхатдан ўтинг","description":"Телеграм бот ёки веб-сайт орқали тез ва осон рўйхатдан ўтинг."},{"title":"Тест режимини танланг","description":"Билетлар, мавзулар, имтиҳон ёки Октагон — ўзингизга қулай режимни танланг."},{"title":"Имтиҳондан ўтинг","description":"Етарлича машқ қилиб, ҳақиқий имтиҳонни муваффақиятли топширинг!"}]},"faq":{"title":"Кўп сўраладиган саволлар","items":[{"question":"Ҳайдовчилик гувоҳномаси олиш учун неча ёш бўлиши керак?","answer":"Ўзбекистонда B тоифали ҳайдовчилик гувоҳномасини олиш учун камида 18 ёшда бўлишингиз керак. A тоифа (мотоцикл) учун ҳам 18 ёш талаб этилади."},{"question":"Имтиҳон нечта саволдан иборат?","answer":"Ҳайдовчилик гувоҳномаси назарий имтиҳони 30 та саволдан иборат. Имтиҳонни топшириш учун камида 27 та саволга тўғри жавоб бериш керак (90%)."},{"question":"Имтиҳонга қанча вақт берилади?","answer":"Назарий имтиҳон учун 20 дақиқа вақт берилади. Шу вақт ичида 30 та саволга жавоб беришингиз керак."},{"question":"OsonPrava бепулми?","answer":"Ҳа, OsonPrava тўлиқ бепул. Барча тестлар, билетлар ва имтиҳон симуляциясидан бепул фойдаланишингиз мумкин."},{"question":"Қандай тест режимлари мавжуд?","answer":"OsonPravada 4 хил режим мавжуд: Билетлар бўйича тест (61 та билет), Мавзулар бўйича тест, Имтиҳон симуляцияси (реал имтиҳон шароитлари) ва Октагон 1v1 (дўстлар билан беллашув)."},{"question":"Телеграм ботдан қандай фойдаланаман?","answer":"Телеграмда @EasyPrava_bot ни қидиринг ва /start буйруғини юборинг. Бот сизга тест ечиш, натижаларни кўриш ва статистикани кузатиш имконини беради."},{"question":"Имтиҳонда қандай мавзулар бўлади?","answer":"Имтиҳонда йўл ҳаракати қоидалари, йўл белгилари, светофор ишоралари, биринчи ёрдам кўрсатиш, транспорт воситасининг техник ҳолати ва бошқа мавзулар бўлади."},{"question":"Нечта хато қилиш мумкин?","answer":"30 та саволдан 3 тагача хато қилиш мумкин. 4 ва ундан кўп хато қилсангиз, имтиҳон топширилмаган ҳисобланади ва қайта топшириш керак бўлади."}]},"cta":{"title":"Ҳозироқ тайёргарликни бошланг!","subtitle":"Минглаб фойдаланувчилар OsonPrava ёрдамида имтиҳондан муваффақиятли ўтишмоқда.","button":"Бепул бошлаш","buttonTelegram":"Телеграм Бот"},"footer":{"description":"Ўзбекистонда ҳайдовчилик гувоҳномаси имтиҳонига тайёргарлик платформаси.","links":"Ҳаволалар","legal":"Ҳуқуқий","privacy":"Махфийлик сиёсати","terms":"Фойдаланиш шартлари","social":"Ижтимоий тармоқлар","telegram":"Телеграм","copyright":"Барча ҳуқуқлар ҳимояланган."}}')}};